sql.if:
AND EXISTS (
    SELECT 1
    FROM TB_LMS_USER_AUTHRT UA
    WHERE UA.USER_ID = U.USER_ID
      AND UA.ORG_ID = #{orgId}
)

HAVING SUM( CASE WHEN S.LCTR_WKNO IS NOT NULL
AND S.LCTR_WKNO >= #{absnWknoFrom}
AND S.LCTR_WKNO <= #{absnWknoTo}
AND ( CASE WHEN NVL(TS.SMSTR_END_YN, 'N') <> 'Y' THEN 0 WHEN W.WKNO IS NULL THEN 1 WHEN NVL(W.LRN_STS_ORD, 0) IN (2, 3) THEN 0 ELSE 1 END ) = 1 THEN 1 ELSE 0 END ) > 0

mapper.sql:
WHERE 1 = 1

    AND EXISTS (
        SELECT 1
        FROM TB_LMS_USER_AUTHRT UA
        WHERE UA.USER_ID = U.USER_ID
          AND UA.ORG_ID = #{orgId}
    )


    AND U.USER_ID = #{userId}


    AND (
    LOWER(U.USERNM) LIKE FN_LIKE_VAL(LOWER(#{keyword}))
    OR U.STDNT_NO LIKE FN_LIKE_VAL(#{keyword})
    OR LOWER(D.DEPTNM) LIKE FN_LIKE_VAL(LOWER(#{keyword}))
    )

WHERE NVL(A.DELYN,'N') = 'N'
AND A.SBJCT_YR = #{searchYr}

    AND SC.DGRS_SMSTR_CHRT = #{searchSmstrCd}


    AND SC.ORG_ID = #{searchOrgId}

mapper.select:
SELECT * FROM ( SELECT ROWNUM AS rnum, X.* FROM ( SELECT ROW_NUMBER() OVER( ORDER BY A.SBJCT_YR DESC, TRIM(A.SBJCT_SMSTR) DESC, A.SBJCTNM ASC, A.DVCLAS_NO ASC ) AS lineNo , A.SBJCT_ID AS sbjctId , A.SBJCT_YR AS sbjctYr , TRIM(A.SBJCT_SMSTR) AS sbjctSmstr , A.CRCLMN_NO AS crclmnNo , A.SBJCTNM AS sbjctnm , A.DVCLAS_NO AS dvclasNo , A.DVCLAS_NCKNM AS dvclasNcknm , A.CRDTS AS crdts , B.USERNM AS profNm , ( SELECT LISTAGG(U2.USERNM, ', ') WITHIN GROUP (ORDER BY SA.SBJCT_ADM_SEQNO) FROM TB_LMS_SBJCT_ADM SA JOIN TB_LMS_USER U2 ON U2.USER_ID = SA.USER_ID WHERE SA.SBJCT_ID = A.SBJCT_ID AND SA.SBJCT_ADM_TYCD = 'COPROF' ) AS coProfNm , ( SELECT LISTAGG(U2.USERNM, ', ') WITHIN GROUP (ORDER BY SA.SBJCT_ADM_SEQNO) FROM TB_LMS_SBJCT_ADM SA JOIN TB_LMS_USER U2 ON U2.USER_ID = SA.USER_ID WHERE SA.SBJCT_ID = A.SBJCT_ID AND SA.SBJCT_ADM_TYCD = 'TUT' ) AS tutor , ( SELECT LISTAGG(U2.USERNM, ', ') WITHIN GROUP (ORDER BY SA.SBJCT_ADM_SEQNO) FROM TB_LMS_SBJCT_ADM SA JOIN TB_LMS_USER U2 ON U2.USER_ID = SA.USER_ID WHERE SA.SBJCT_ID = A.SBJCT_ID AND SA.SBJCT_ADM_TYCD = 'ASSI' ) AS asst , O.ORGNM AS orgnm , A.SMSTR_CHRT_ID AS smstrChrtId , A.USEYN AS useyn
LEFT JOIN TB_LMS_ORG O ON O.ORG_ID = SC.ORG_ID
) X WHERE ROWNUM <= (#{firstIndex} + #{listScale}) ) WHERE rnum > #{firstIndex}

WITH , , CURRENT_WK AS ( SELECT MAX(LCTR_WKNO) AS CURR_WKNO FROM TB_LMS_LCTR_WKNO_SCHDL WHERE SBJCT_ID = #{sbjctId} AND NVL(DELYN, 'N') = 'N' AND LCTR_WKNO_SYMD IS NOT NULL AND LCTR_WKNO_SYMD <> '00000000' AND LCTR_WKNO_SYMD <= TO_CHAR(SYSDATE, 'YYYYMMDD') ), STDNT_BASE AS ( SELECT U.USER_ID , U.USERNM , U.STDNT_NO , D.DEPTNM , NULL AS ENTRNS_YR , E.SCYR AS GRADE , SUM( CASE WHEN S.LCTR_WKNO IS NULL THEN 0 WHEN NVL(TS.SMSTR_END_YN, 'N') <> 'Y' THEN 0 WHEN W.WKNO IS NULL THEN 1 WHEN NVL(W.LRN_STS_ORD, 0) IN (2, 3) THEN 0 ELSE 1 END ) AS ABSNCE_CNT , SUM( CASE WHEN S.LCTR_WKNO IS NOT NULL AND NVL(W.LRN_STS_ORD, 0) = 3 THEN 1 ELSE 0 END ) AS ATND_CNT , SUM( CASE WHEN S.LCTR_WKNO IS NOT NULL AND NVL(W.LRN_STS_ORD, 0) = 2 THEN 1 ELSE 0 END ) AS LATE_CNT FROM TB_LMS_ATNDLC E JOIN TB_LMS_USER U ON U.USER_ID = E.USER_ID JOIN TB_LMS_DEPT D ON D.DEPT_ID = U.DEPT_ID CROSS JOIN CURRENT_WK CW JOIN SBJCT_TERM_STS TS ON TS.SBJCT_ID = E.SBJCT_ID LEFT JOIN TB_LMS_LCTR_WKNO_SCHDL S ON S.SBJCT_ID = E.SBJCT_ID AND NVL(S.DELYN, 'N') = 'N'
LEFT JOIN WK_USER_LRN_STS W ON W.USER_ID = U.USER_ID AND W.SBJCT_ID = E.SBJCT_ID AND W.WKNO = S.LCTR_WKNO WHERE E.SBJCT_ID = #{sbjctId} AND E.ATNDLC_STSCD = 'APPROVE' AND NVL(E.AUDITYN, 'N') = 'N'
GROUP BY U.USER_ID , U.USERNM , U.STDNT_NO , D.DEPTNM , E.SCYR
) SELECT * FROM ( SELECT ROWNUM AS rnum, P.* FROM ( SELECT ROW_NUMBER() OVER(ORDER BY S.STDNT_NO ASC, S.USER_ID ASC) AS lineNo , COUNT(1) OVER() AS totalCnt , S.USER_ID AS userId , S.USERNM AS usernm , S.STDNT_NO AS stdntNo , S.DEPTNM AS deptnm , S.ENTRNS_YR AS entyR , S.GRADE AS scyr , S.ABSNCE_CNT AS absnCnt , S.ATND_CNT AS atndCnt , S.LATE_CNT AS lateCnt FROM STDNT_BASE S ORDER BY S.STDNT_NO ASC, S.USER_ID ASC ) P WHERE ROWNUM <= (#{firstIndex} + #{listScale}) ) WHERE rnum > #{firstIndex}

WITH , , WK_LIST AS ( SELECT DISTINCT S.LCTR_WKNO AS WKNO FROM TB_LMS_LCTR_WKNO_SCHDL S CROSS JOIN SBJCT_TERM_STS TS WHERE S.SBJCT_ID = #{sbjctId} AND NVL(S.DELYN, 'N') = 'N'
), BASE_STDNT AS ( SELECT DISTINCT E.USER_ID , E.SBJCT_ID FROM TB_LMS_ATNDLC E JOIN TB_LMS_USER U ON U.USER_ID = E.USER_ID JOIN TB_LMS_DEPT D ON D.DEPT_ID = U.DEPT_ID WHERE E.SBJCT_ID = #{sbjctId} AND E.ATNDLC_STSCD = 'APPROVE' AND NVL(E.AUDITYN, 'N') = 'N'
AND EXISTS ( SELECT 1 FROM TB_LMS_USER_AUTHRT UA WHERE UA.USER_ID = U.USER_ID AND UA.ORG_ID = #{orgId} )
) SELECT WK.WKNO AS wkNo , COUNT(DISTINCT A.USER_ID) AS totalCnt , SUM( CASE WHEN W.WKNO IS NULL THEN 1 WHEN NVL(W.LRN_STS_ORD, 0) IN (2, 3) THEN 0 ELSE 1 END ) AS notLrnnCnt , CASE WHEN COUNT(DISTINCT A.USER_ID) = 0 THEN 0 ELSE ROUND( SUM( CASE WHEN W.WKNO IS NULL THEN 1 WHEN NVL(W.LRN_STS_ORD, 0) IN (2, 3) THEN 0 ELSE 1 END ) / COUNT(DISTINCT A.USER_ID) * 100 , 2) END AS notLrnnRt FROM WK_LIST WK JOIN BASE_STDNT A ON A.SBJCT_ID = #{sbjctId} LEFT JOIN WK_USER_LRN_STS W ON W.USER_ID = A.USER_ID AND W.SBJCT_ID = A.SBJCT_ID AND W.WKNO = WK.WKNO GROUP BY WK.WKNO

SELECT * FROM ( SELECT ROWNUM AS rnum, X.* FROM ( SELECT ROW_NUMBER() OVER(ORDER BY L.ACTV_DTTM DESC) AS lineNo , TO_CHAR(TO_DATE(L.ACTV_DTTM,'YYYYMMDDHH24MISS'),'YYYY.MM.DD HH24:MI:SS') AS actDttm , L.USER_REQ_URL AS actConts , NVL(L.CNTN_BRWSR, L.REQ_TYCD) AS deviceNm , L.CNTN_IP AS ipAddr FROM TB_LMS_LOG_USER_ACTV L WHERE L.SBJCT_ID = #{sbjctId} AND L.USER_ID = #{userId} AND EXISTS ( SELECT 1 FROM TB_LMS_ATNDLC A WHERE A.USER_ID = L.USER_ID AND A.SBJCT_ID = #{sbjctId} AND A.ATNDLC_STSCD = 'APPROVE' AND NVL(A.AUDITYN, 'N') = 'N' )
AND ( L.USER_REQ_URL LIKE '%' || #{keyword} || '%' OR NVL(L.CNTN_BRWSR, L.REQ_TYCD) LIKE '%' || #{keyword} || '%' OR L.CNTN_IP LIKE '%' || #{keyword} || '%' )
ORDER BY L.ACTV_DTTM DESC ) X WHERE ROWNUM <= (#{firstIndex} + #{listScale}) ) WHERE rnum > #{firstIndex}

mapper.update:
UPDATE TB_LMS_BYWKNO_USER_LRN_STS
/* 이전 학습상태로 복원한다. 수동 출석처리로 생성된 건은 취소 후 ABSNT로 남는다. */
SET LRN_STSCD = CASE WHEN NVL(BFR_LRN_STSCD,'ABSNT') = 'ATND' THEN 'CMPTN' ELSE NVL(BFR_LRN_STSCD,'ABSNT') END
  , BFR_LRN_STSCD = NULL
  , MDFR_ID = #{mdfrId}
  , MOD_DTTM = TO_CHAR(SYSDATE,'YYYYMMDDHH24MISS')
WHERE USER_ID = #{userId}
  AND LCTR_WKNO_SCHDL_ID = #{lctrWknoSchdlId}

mapper.select:
WITH , , CURRENT_WK AS ( SELECT MAX(LCTR_WKNO) AS CURR_WKNO FROM TB_LMS_LCTR_WKNO_SCHDL WHERE SBJCT_ID = #{sbjctId} AND NVL(DELYN, 'N') = 'N' AND LCTR_WKNO_SYMD IS NOT NULL AND LCTR_WKNO_SYMD <> '00000000' AND LCTR_WKNO_SYMD <= TO_CHAR(SYSDATE, 'YYYYMMDD') ), STDNT_BASE AS ( SELECT U.USER_ID , U.USERNM , U.STDNT_NO , D.DEPTNM , NULL AS ENTRNS_YR , E.SCYR AS GRADE , SUM( CASE WHEN S.LCTR_WKNO IS NULL THEN 0 WHEN NVL(TS.SMSTR_END_YN, 'N') <> 'Y' THEN 0 WHEN W.WKNO IS NULL THEN 1 WHEN NVL(W.LRN_STS_ORD, 0) IN (2, 3) THEN 0 ELSE 1 END ) AS ABSNCE_CNT , SUM( CASE WHEN S.LCTR_WKNO IS NOT NULL AND NVL(W.LRN_STS_ORD, 0) = 3 THEN 1 ELSE 0 END ) AS ATND_CNT , SUM( CASE WHEN S.LCTR_WKNO IS NOT NULL AND NVL(W.LRN_STS_ORD, 0) = 2 THEN 1 ELSE 0 END ) AS LATE_CNT FROM TB_LMS_ATNDLC E JOIN TB_LMS_USER U ON U.USER_ID = E.USER_ID JOIN TB_LMS_DEPT D ON D.DEPT_ID = U.DEPT_ID CROSS JOIN CURRENT_WK CW JOIN SBJCT_TERM_STS TS ON TS.SBJCT_ID = E.SBJCT_ID LEFT JOIN TB_LMS_LCTR_WKNO_SCHDL S ON S.SBJCT_ID = E.SBJCT_ID AND NVL(S.DELYN, 'N') = 'N'
LEFT JOIN WK_USER_LRN_STS W ON W.USER_ID = U.USER_ID AND W.SBJCT_ID = E.SBJCT_ID AND W.WKNO = S.LCTR_WKNO WHERE E.SBJCT_ID = #{sbjctId} AND E.ATNDLC_STSCD = 'APPROVE' AND NVL(E.AUDITYN, 'N') = 'N'
GROUP BY U.USER_ID , U.USERNM , U.STDNT_NO , D.DEPTNM , E.SCYR ) SELECT USER_ID AS userId , USERNM AS usernm , STDNT_NO AS stdntNo , DEPTNM AS deptnm , ENTRNS_YR AS entyR , GRADE AS scyr , ABSNCE_CNT AS absnCnt , ATND_CNT AS atndCnt , LATE_CNT AS lateCnt FROM STDNT_BASE WHERE USER_ID = #{userId}

SELECT COUNT(1)
FROM TB_LMS_LCTR_WKNO_SCHDL W
WHERE W.SBJCT_ID = #{sbjctId}
AND W.LCTR_WKNO = #{wkNo}
AND NVL(W.DELYN, 'N') = 'N'

    AND W.LCTR_WKNO_SCHDL_ID = #{lctrWknoSchdlId}
